/**
 * Blazor JavaScript initializer for rc-webcomponents events.
 *
 * Generated by `yarn codegen:blazor` from the element typings. Do not edit by
 * hand: change the component source instead.
 *
 * Copy it to your app's wwwroot as `{AssemblyName}.lib.module.js`, or call
 * `registerRcEvents(blazor)` from your own initializer. Pair it with
 * RcWebComponents.Events.cs.
 */

/** Every `rc-*` event the elements dispatch. All bubble and are composed. */
export const RC_EVENTS = [
  'rc-adaptive-menu-toggle',
  'rc-app-bar-scroll',
  'rc-bottom-sheet-resize-start',
  'rc-bottom-sheet-snap',
  'rc-button-toggle',
  'rc-carousel-change',
  'rc-change',
  'rc-chip-change',
  'rc-chip-group-toggle',
  'rc-chip-remove',
  'rc-combobox-create',
  'rc-data-table-sort',
  'rc-dialog-cancel',
  'rc-dialog-close',
  'rc-dialog-open',
  'rc-dialog-request-close',
  'rc-dialog-toggle',
  'rc-disclosure-toggle',
  'rc-fab-menu-toggle',
  'rc-formatting-change',
  'rc-list-item-toggle',
  'rc-list-reorder',
  'rc-listbox-change',
  'rc-menu-activate',
  'rc-menu-button-toggle',
  'rc-menu-close',
  'rc-mode-change',
  'rc-navigation-rail-toggle',
  'rc-page-turner-change',
  'rc-pagination-change',
  'rc-popover-toggle',
  'rc-progress-complete',
  'rc-range-slider-change',
  'rc-range-slider-input',
  'rc-search-bar-clear',
  'rc-search-bar-input',
  'rc-search-bar-suggestion-select',
  'rc-search-bar-toggle',
  'rc-segmented-button-change',
  'rc-select-change',
  'rc-select-close',
  'rc-select-open',
  'rc-slider-change',
  'rc-slider-input',
  'rc-snackbar-action',
  'rc-snackbar-close',
  'rc-splitter-change',
  'rc-switch-change',
  'rc-textarea-blur',
  'rc-textarea-change',
  'rc-textarea-focus',
  'rc-textarea-select',
  'rc-toolbar-action',
  'rc-transfer-list-change',
  'rc-virtual-canvas-pointer',
  'rc-virtual-canvas-render',
  'rc-virtual-scroller-range',
];

/** A JSON copy of an event detail without elements, DOM events, functions, or cycles. */
export function toEventArgs(value, seen = new WeakSet()) {
  const { Event, Node } = globalThis;

  if (value === null || typeof value !== 'object') {
    return typeof value === 'function' ? undefined : value;
  }

  if (
    (typeof Node !== 'undefined' && value instanceof Node) ||
    (typeof Event !== 'undefined' && value instanceof Event) ||
    seen.has(value)
  ) {
    return undefined;
  }

  // Only the current path, so a value shared by two fields is kept in both.
  seen.add(value);

  try {
    if (Array.isArray(value)) {
      return value.map((item) => toEventArgs(item, seen) ?? null);
    }

    const args = {};

    for (const [key, item] of Object.entries(value)) {
      const converted = toEventArgs(item, seen);

      if (converted !== undefined) {
        args[key] = converted;
      }
    }

    return args;
  } finally {
    seen.delete(value);
  }
}

const registered = new WeakSet();

/**
 * Registers each `rc-*` event, passing its detail as the event arguments.
 * Blazor throws on a second registration, so later calls do nothing.
 */
export function registerRcEvents(blazor) {
  if (registered.has(blazor)) {
    return;
  }

  registered.add(blazor);

  for (const name of RC_EVENTS) {
    blazor.registerCustomEventType(name, {
      createEventArgs: (event) => toEventArgs(event.detail) ?? {},
    });
  }
}

/** Blazor Web App initializer. */
export function afterWebStarted(blazor) {
  registerRcEvents(blazor);
}

/** Blazor Server and WebAssembly initializer. */
export function afterStarted(blazor) {
  registerRcEvents(blazor);
}
